// === Tab: mySketch ===
let geom
let warpStroke
let warpFill
let font

async function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL)
	font = await loadFont('https://fonts.gstatic.com/s/prompt/v12/-W__XJnvUD7dzB26Z9AcZkIzeg.ttf')
	textSize(150)
	textAlign(CENTER, CENTER)
	geom = font.textToModel('p5*js', 0, 0, {
		sampleFactor: 0.5
	})

	warpStroke = baseStrokeShader().modify(warp)
	warpFill = baseColorShader().modify(warp)

	background('#F52CA6')
}

function warp() {
	const frame = uniformFloat(() => max(0, frameCount - 60))
	getObjectInputs((inputs) => {
		const s = 0.005
		inputs.position.xy += frame * 0.2 * [
			noise(inputs.position.x * s, inputs.position.y * s, frame * 0.002),
			noise(inputs.position.x * s, inputs.position.y * s, frame * 0.002 + 100)
		]
		return inputs
	})
}

function draw() {
	const x = -width/2 + 100 + max(0, frameCount - 60) * 2
	if (x < width/2 - 100) {
		push()
		translate(x, 0)
		strokeShader(warpStroke)
		shader(warpFill)
		fill(255)
		stroke(0, 150)
		rotate(PI/2)
		model(geom)
		pop()
	}
}

